import{_ as e,C as t,c as r,o as i,j as l,G as n,b as a,a0 as s,a as d,w as o,a1 as k}from"./chunks/framework.DKRgXLPU.js";const g=JSON.parse('{"title":"Taktisk tænkning i petanque","description":"","frontmatter":{},"headers":[],"relativePath":"da/education/tactics/index.md","filePath":"da/education/tactics/index.md"}');const u=e({name:"da/education/tactics/index.md"},[["render",function(e,g,u,p,h,f){const c=t("AdBanner"),m=t("Mermaid");return i(),r("div",null,[g[2]||(g[2]=l("h1",{id:"taktisk-tænkning-i-petanque",tabindex:"-1"},[d("Taktisk tænkning i petanque "),l("a",{class:"header-anchor",href:"#taktisk-tænkning-i-petanque","aria-label":'Permalink to "Taktisk tænkning i petanque"'},"​")],-1)),n(c),g[3]||(g[3]=l("p",null,"På eliteniveau forudsættes teknisk færdighed. Det, der adskiller vindere fra resten, er taktisk intelligens - at vide, hvilket kast man skal forsøge, og hvornår. De bedste spillere læser spillet flere træk fremad og udnytter enhver fordel.",-1)),g[4]||(g[4]=l("div",{class:"tip custom-block"},[l("p",{class:"custom-block-title"},"Kerneprincippet"),l("p",null,[l("strong",null,"På eliteniveau er forskellen sjældent teknikken - det er beslutningstagningen."),d(" Det hold, der laver færrest taktiske fejl, vinder.")])],-1)),g[5]||(g[5]=l("h2",{id:"hurtig-beslutningsramme",tabindex:"-1"},[d("Hurtig beslutningsramme "),l("a",{class:"header-anchor",href:"#hurtig-beslutningsramme","aria-label":'Permalink to "Hurtig beslutningsramme"'},"​")],-1)),(i(),a(k,null,{default:o(()=>[n(m,{id:"mermaid-16",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BDin%20tur%5D%20--%3E%20B%7BAre%20you%20holding%3F%7D%0A%20%20%20%20B%20--%3E%7CYes%7C%20C%7BOpponent%20has%20boules%3F%7D%0A%20%20%20%20B%20--%3E%7CNo%7C%20D%7BCan%20you%20point%20closer%3F%7D%0A%0A%20%20%20%20C%20--%3E%7CYes%7C%20E%5BVent%20og%20planl%C3%A6g%5D%0A%20%20%20%20C%20--%3E%7CNo%7C%20F%7BSafe%20to%20add%20points%3F%7D%0A%0A%20%20%20%20F%20--%3E%7CYes%7C%20G%5BTilf%C3%B8j%20point%20omhyggeligt%5D%0A%20%20%20%20F%20--%3E%7CNo%7C%20H%5BSpil%20sikkert%2Fbloker%5D%0A%0A%20%20%20%20D%20--%3E%7CYes%2C%20high%20%25%7C%20I%5BPunkt%5D%0A%20%20%20%20D%20--%3E%7CM%C3%A5ske%7C%20J%7BCan%20you%20shoot%3F%7D%0A%20%20%20%20D%20--%3E%7CNo%7C%20K%5BFlyt%20donkraft%20eller%20blok%5D%0A%0A%20%20%20%20J%20--%3E%7CYes%2C%20%3E60%25%7C%20L%5BSkud%5D%0A%20%20%20%20J%20--%3E%7CNo%7C%20K%0A%0A%20%20%20%20style%20B%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23e3f2fd%0A%20%20%20%20style%20D%20fill%3A%23fff3e0%0A%20%20%20%20style%20F%20fill%3A%23fff3e0%0A%20%20%20%20style%20J%20fill%3A%23ffebee%0A"})]),fallback:o(()=>[...g[0]||(g[0]=[d(" Loading... ",-1)])]),_:1})),g[6]||(g[6]=s('<h2 id="den-taktiske-tankegang" tabindex="-1">Den taktiske tankegang <a class="header-anchor" href="#den-taktiske-tankegang" aria-label="Permalink to &quot;Den taktiske tankegang&quot;">​</a></h2><h3 id="tænk-i-sandsynligheder" tabindex="-1">Tænk i sandsynligheder <a class="header-anchor" href="#tænk-i-sandsynligheder" aria-label="Permalink to &quot;Tænk i sandsynligheder&quot;">​</a></h3><p>Hvert kast har en sandsynlighed for succes. God taktik betyder at vælge kast hvor:</p><ul><li>Sandsynligheden for succes er høj nok</li><li>Belønningen retfærdiggør risikoen</li><li>Fiasko gør ikke for ondt</li></ul><p><strong>Eksempel på afgørelse:</strong></p><ul><li>Svært skud: 40% succes, får 3 point</li><li>Sikkerhedspoint: 80% succes, opnår 1 point</li></ul><p>Hvilken er bedst? Det afhænger af resultatet, situationen og din selvtillid.</p><h3 id="overvej-alle-muligheder" tabindex="-1">Overvej alle muligheder <a class="header-anchor" href="#overvej-alle-muligheder" aria-label="Permalink to &quot;Overvej alle muligheder&quot;">​</a></h3><p>Overvej følgende før hvert kast:</p><ol><li><strong>Point:</strong> Placer en kugle nær målkuglen</li><li><strong>Skyd:</strong> Fjern en modstanders kugle</li><li><strong>Blokering:</strong> Placer en kugle for at blokere</li><li><strong>Flyt donkraften:</strong> Ramte med vilje donkraften</li><li><strong>Offer:</strong> Accepter en dårlig position for at etablere dig senere</li></ol><p>Vælg ikke det oplagte valg som standard. Tænk over alternativer.</p><h3 id="læs-situationen" tabindex="-1">Læs situationen <a class="header-anchor" href="#læs-situationen" aria-label="Permalink to &quot;Læs situationen&quot;">​</a></h3><p>Faktorer at overveje:</p><ul><li>Nuværende score (hvem er foran, med hvor meget)</li><li>Tilbageværende boules (dine og deres)</li><li>Position på terrænet</li><li>Modstanderens tendenser</li><li>Dit holds styrker</li></ul><h2 id="kernetaktiske-principper" tabindex="-1">Kernetaktiske principper <a class="header-anchor" href="#kernetaktiske-principper" aria-label="Permalink to &quot;Kernetaktiske principper&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">De 6 taktiske principper</p><ol><li><strong>Kontroller donkraften</strong> - Position er magt</li><li><strong>Afstands- og overfladestrategi</strong> - Tilpas dig til forholdene</li><li><strong>Diktér spillestilen</strong> - Tving dine styrker frem</li><li><strong>Håndtering af risiko vs. belønning</strong> - Match risiko med situation</li><li><strong>Brug boules klogt</strong> - Giver nogle gange 1 bold væk for at undgå 3</li><li><strong>Tænk fremad</strong> - Visualiser de næste 2-3 træk</li></ol></div><h3 id="princip-1-styr-donkraften" tabindex="-1">Princip 1: Styr donkraften <a class="header-anchor" href="#princip-1-styr-donkraften" aria-label="Permalink to &quot;Princip 1: Styr donkraften&quot;">​</a></h3><p>Holdet, der kontrollerer donkraftens position, har en betydelig fordel.</p><p><strong>Måder at kontrollere:</strong></p><ul><li>Vind retten til at kaste målscoren</li><li>Flyt donkraften til et gunstigt terræn</li><li>Beskyt donkraften mod at blive flyttet</li></ul><p><strong>Strategi for placering af knægte:</strong></p><ul><li>Kort jack: Foretrækker at skyde, lettere at ramme mål på tæt hold</li><li>Langt stik: Foretrækker at pege, det bliver vanskeligere at skyde</li><li>Nær forhindringer: Skaber udfordringer for modstandere</li></ul><p><strong>Udnyt modstanderens svagheder:</strong></p><ul><li>Observer deres pegeteknik - bruger de altid den samme bue eller stil?</li><li>Hvis de ikke kan tilpasse sig (f.eks. kun rulle, kun lobbe), så placer målgriben for at fremtvinge ubehagelige kast.</li><li>Placer donkraften i afstande eller positioner, der afdækker dens begrænsninger</li><li>Udnyt kun en svaghed, hvis du ikke deler den - overvej først dit eget teams styrker.</li></ul><h3 id="princip-2-afstands-og-overfladestrategi" tabindex="-1">Princip 2: Afstands- og overfladestrategi <a class="header-anchor" href="#princip-2-afstands-og-overfladestrategi" aria-label="Permalink to &quot;Princip 2: Afstands- og overfladestrategi&quot;">​</a></h3><p>Den optimale balance mellem at sigte og skyde afhænger i høj grad af afstand og terræn:</p><div class="info custom-block"><p class="custom-block-title">Afstandsstrategi</p><p><strong>Kort (6-7m):</strong> Foretrækker at skyde - lettere at ramme på tæt hold <strong>Mellem (7-9 m):</strong> Overfladen er vigtigst</p><ul><li>Glat overflade → optag mere</li><li>Ru overflade → peg mere</li></ul><p><strong>Lang (9-11 m):</strong> Foretrækker at pege - skudpræcisionen falder betydeligt</p></div>',27)),(i(),a(k,null,{default:o(()=>[n(m,{id:"mermaid-264",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BAfstand%5D%20--%3E%20B%5B6-7%20m%20kort%5D%0A%20%20%20%20A%20--%3E%20C%5B7-9m%20Mellem%5D%0A%20%20%20%20A%20--%3E%20D%5B9-11%20m%20lang%5D%0A%0A%20%20%20%20B%20--%3E%20E%5BSkyd%20mere%5D%0A%20%20%20%20C%20--%3E%20F%7BSurface%3F%7D%0A%20%20%20%20D%20--%3E%20G%5BPoint%20More%5D%0A%0A%3CAdInArticle%20%2F%3E%0A%0A%20%20%20%20F%20--%3E%7CSmooth%7C%20H%5BSkyd%20mere%5D%0A%20%20%20%20F%20--%3E%7CRough%7C%20I%5BPoint%20More%5D%0A%0A%20%20%20%20style%20E%20fill%3A%23ffcdd2%0A%20%20%20%20style%20H%20fill%3A%23ffcdd2%0A%20%20%20%20style%20I%20fill%3A%23c8e6c9%0A%20%20%20%20style%20G%20fill%3A%23c8e6c9%0A"})]),fallback:o(()=>[...g[1]||(g[1]=[d(" Loading... ",-1)])]),_:1})),g[7]||(g[7]=s('<p><strong>Din personlige skudprocent:</strong></p><ul><li>Hvis du skyder med en succesrate på 75%+, så skyd oftere</li><li>Overvej at skyde for at reducere modstanderens point (selvom du ikke tager føringen)</li><li>At skyde for at reducere modstanderens scoringskugler (fra 3 ned til 1) er værdifuld skadekontrol.</li></ul><p><strong>Skydning som en langsigtet strategi:</strong></p><ul><li>Hvis du skyder med alle dine kugler, så overvej din samlede succesrate</li><li>Beregn: Når du rammer alle slag, får du betydeligt flere point</li><li>Selv at misse nogle skud kan reducere modstanderens point</li><li>Eksempel: Bom 1-2 skud, men fjern stadig trusler, og vind så stort, når du rammer alle</li><li>Dette er en kalkuleret risiko - accepter nogle tabte gevinster for større gevinster, når det virker</li></ul><h3 id="princip-3-dikter-spillestilen" tabindex="-1">Princip 3: Diktér spillestilen <a class="header-anchor" href="#princip-3-dikter-spillestilen" aria-label="Permalink to &quot;Princip 3: Diktér spillestilen&quot;">​</a></h3><p>På eliteniveau kan de fleste spillere både pege og skyde godt. Nøglen er at tvinge spillet ind i dit holds stærkeste stil.</p><p><strong>Hvis dit hold har stærke skytter:</strong></p><ul><li>Skyd så meget som muligt - udnyt din fordel</li><li>Spild ikke din styrke ved at pege, når du kan dominere ved at skyde</li><li>Styr spillet ved at fjerne trusler, før de ophobes</li><li>Kort til mellemstort stik sikrer effektiv optagelse</li></ul><p><strong>Mod lige så stærke skytter:</strong></p><ul><li>Negér dem som lette mål ved at skyde først</li><li>Spil på lang afstand for at reducere alles skudprocent</li><li>Det hold, der skyder først, styrer ofte slutningen</li></ul><p><strong>Hvis modstandere skyder bedre end dig:</strong></p><ul><li>Spil konsekvent med long jack - selv eliteskytter taber procent ved 10m+</li><li>Tving en pointkamp frem, hvor du kan konkurrere</li><li>Få dem til at skyde fra vanskelige vinkler eller gennem forhindringer</li></ul><h3 id="princip-4-handter-risiko-vs-belønning" tabindex="-1">Princip 4: Håndter risiko vs. belønning <a class="header-anchor" href="#princip-4-handter-risiko-vs-belønning" aria-label="Permalink to &quot;Princip 4: Håndter risiko vs. belønning&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Situation</th><th>Risikotolerance</th></tr></thead><tbody><tr><td>Komfortabelt fremad</td><td>Lav - beskyt din ledning</td></tr><tr><td>Luk spillet</td><td>Mellemstore - beregnede risici</td></tr><tr><td>Bagud betydeligt</td><td>Høj - behov for at tage chancer</td></tr><tr><td>Endelig afslutning</td><td>Afhænger af scoreforskellen</td></tr></tbody></table><h3 id="princip-5-brug-dine-boules-klogt" tabindex="-1">Princip 5: Brug dine boules klogt <a class="header-anchor" href="#princip-5-brug-dine-boules-klogt" aria-label="Permalink to &quot;Princip 5: Brug dine boules klogt&quot;">​</a></h3><p>Boule-ledelse adskiller elitespillere:</p><ul><li>Når modstanderen løber tør for kugler, så vælg omhyggeligt: læg point til eller spil sikkert?</li><li>Når du er bagud, så beregn om du realistisk set kan tage pointet tilbage</li><li>Nogle gange er det bedre at give 1 point væk end at spilde kugler og give 3 væk</li><li>Hold styr på resterende kugler - dine og deres - til enhver tid</li></ul><h3 id="princip-6-tænk-flere-skridt-fremad" tabindex="-1">Princip 6: Tænk flere skridt fremad <a class="header-anchor" href="#princip-6-tænk-flere-skridt-fremad" aria-label="Permalink to &quot;Princip 6: Tænk flere skridt fremad&quot;">​</a></h3><p>Elitetankegang:</p><ul><li>Før du kaster, visualiser de næste 2-3 kugler fra begge hold</li><li>Hvad er din modstanders bedste reaktion, hvis du lykkes? Hvis du fejler?</li><li>Hvordan forbereder dette kast dig på dit næste?</li><li>Overvej slutspillets scenarie fra den nuværende position</li></ul><h2 id="almindelige-taktiske-situationer" tabindex="-1">Almindelige taktiske situationer <a class="header-anchor" href="#almindelige-taktiske-situationer" aria-label="Permalink to &quot;Almindelige taktiske situationer&quot;">​</a></h2><h3 id="du-holder-og-modstanderen-har-kugler-tilbage" tabindex="-1">Du holder, og modstanderen har kugler tilbage <a class="header-anchor" href="#du-holder-og-modstanderen-har-kugler-tilbage" aria-label="Permalink to &quot;Du holder, og modstanderen har kugler tilbage&quot;">​</a></h3><p>Du skal vente - det er deres tur til at kaste. Brug denne tid til at:</p><ul><li>Analyser hvad de sandsynligvis vil gøre</li><li>Planlæg din reaktion på deres mulige kast</li><li>Forbliv fokuseret og klar</li></ul><h3 id="du-holder-og-modstanderen-har-ikke-flere-boules" tabindex="-1">Du holder, og modstanderen har ikke flere boules <a class="header-anchor" href="#du-holder-og-modstanderen-har-ikke-flere-boules" aria-label="Permalink to &quot;Du holder, og modstanderen har ikke flere boules&quot;">​</a></h3><p>Nu kan du spille dine resterende kugler. <strong>Muligheder:</strong></p><ul><li>Tilføj flere point, hvis du kan gøre det sikkert</li><li>Blok for at beskytte mod donkraftbevægelse</li><li>Spil sikkert - risiker ikke at forvandle en 2-points sejr til et nederlag</li></ul><p><strong>Vigtig beslutning:</strong> Er risikoen ved at tilføje point værd at potentielt åbne spillet op for?</p><h3 id="du-holder-ikke" tabindex="-1">Du holder ikke <a class="header-anchor" href="#du-holder-ikke" aria-label="Permalink to &quot;Du holder ikke&quot;">​</a></h3><p>Du skal kaste. <strong>Muligheder:</strong></p><ul><li>Point tættere end deres bedste kugle</li><li>Skyd deres bedste kugle</li><li>Flyt målkuglen til dine kugler</li><li>Bloker for at begrænse deres point (hvis du ikke kan tage pointet)</li></ul><p><strong>Beslutningsfaktorer:</strong> Din skudprocent, antal kugler tilbage (begge hold), nuværende score</p><h3 id="sidste-boule-situationer" tabindex="-1">Sidste boule-situationer <a class="header-anchor" href="#sidste-boule-situationer" aria-label="Permalink to &quot;Sidste boule-situationer&quot;">​</a></h3><p>Når du har den sidste kugle:</p><ul><li>Maksimalt tryk, men også maksimal kontrol</li><li>Tag dig god tid - vurder alle muligheder</li><li>Overvej: peg, skyd eller flyt donkraften?</li><li>Udfør med fuldt engagement</li></ul><p>Når modstanderen har den sidste kugle:</p><ul><li>Du har gjort hvad du kunne - accepter resultatet</li><li>Hvis det er muligt, så skab en situation uden en nem løsning for dem</li><li>Flere trusler er bedre end én</li></ul><h2 id="at-læse-dine-modstandere" tabindex="-1">At læse dine modstandere <a class="header-anchor" href="#at-læse-dine-modstandere" aria-label="Permalink to &quot;At læse dine modstandere&quot;">​</a></h2><p>På eliteniveau er scouting vigtig. Kend dine modstandere, før du spiller.</p><h3 id="intelligens-før-kampen" tabindex="-1">Intelligens før kampen <a class="header-anchor" href="#intelligens-før-kampen" aria-label="Permalink to &quot;Intelligens før kampen&quot;">​</a></h3><ul><li>Hvad er deres foretrukne spillestil (skydende vs. pegende hold)?</li><li>Hvem er deres stærkeste skytter? Pointer?</li><li>Hvilke afstande foretrækker de?</li><li>Hvordan klarer de sig under pres i finalerne?</li></ul><h3 id="observation-under-kampen" tabindex="-1">Observation under kampen <a class="header-anchor" href="#observation-under-kampen" aria-label="Permalink to &quot;Observation under kampen&quot;">​</a></h3><ul><li>Spor deres succesrater gennem hele kampen</li><li>Læg mærke til om nogen har en fridag</li><li>Identificér hvem der håndterer pres godt, og hvem der ikke gør det</li><li>Juster din donkrafts placering baseret på, hvad du observerer</li></ul><h3 id="udnyt-det-du-finder" tabindex="-1">Udnyt det, du finder <a class="header-anchor" href="#udnyt-det-du-finder" aria-label="Permalink to &quot;Udnyt det, du finder&quot;">​</a></h3><ul><li>Fokuser på de svagere spillere, når det er muligt</li><li>Tving deres svage skytter til at skyde, eller deres svage pointer til at pege</li><li>Hvis nogen har det svært, så hold presset på dem</li></ul><h2 id="i-dette-afsnit" tabindex="-1">I dette afsnit <a class="header-anchor" href="#i-dette-afsnit" aria-label="Permalink to &quot;I dette afsnit&quot;">​</a></h2><ul><li><strong><a href="/da/uddannelse/taktik/sandsynlighed">Sandsynlighedsbaserede beslutninger</a></strong> - Brug af matematik til at træffe bedre valg</li></ul><h2 id="resume-alle-taktiske-regler" tabindex="-1">Resumé: Alle taktiske regler <a class="header-anchor" href="#resume-alle-taktiske-regler" aria-label="Permalink to &quot;Resumé: Alle taktiske regler&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Regel nr. 1: Sandsynlighedsreglen</p><p><strong>Vælg kast hvor sandsynligheden for succes retfærdiggør risikoen.</strong> Overvej: succesrate, belønning hvis succes, omkostninger hvis mislykkes</p></div><div class="tip custom-block"><p class="custom-block-title">Regel nr. 2: Jack-kontrolreglen</p><p><strong>Det hold, der kontrollerer donkraftens position, har fordelen.</strong> Brug knægtens placering til at udnytte modstanderens svagheder og favorisere dine styrker</p></div><div class="tip custom-block"><p class="custom-block-title">Regel nr. 3: Afstandsreglen</p><p><strong>Kort afstand favoriserer skud, lang afstand favoriserer pegning.</strong> Mellemdistance: Underlagets kvalitet bestemmer balancen</p></div><div class="tip custom-block"><p class="custom-block-title">Regel nr. 4: Stilreglen</p><p><strong>Tving spillet ind i dit holds stærkeste stil.</strong> Hvis I er dygtige skytter, så skyd mere. Spild ikke jeres fordel.</p></div><div class="tip custom-block"><p class="custom-block-title">Regel nr. 5: Reglen for boulehåndtering</p><p><strong>Nogle gange er det bedre at give 1 point ind end at risikere 3.</strong> Vid, hvornår du skal begrænse dine tab, og gem dine kugler til næste omgang</p></div><div class="tip custom-block"><p class="custom-block-title">Regel nr. 6: Reglen om at tænke fremad</p><p><strong>Visualiser de næste 2-3 træk fra begge hold.</strong> Hvad er deres bedste svar? Hvordan forbereder dette dit næste kast?</p></div><div class="tip custom-block"><p class="custom-block-title">Regel nr. 7: Spejderreglen</p><p><strong>Kend dine modstandere, før du spiller.</strong> Spor deres præferencer, succesrater og presreaktioner</p></div><h2 id="vigtig-konklusion" tabindex="-1">Vigtig konklusion <a class="header-anchor" href="#vigtig-konklusion" aria-label="Permalink to &quot;Vigtig konklusion&quot;">​</a></h2><blockquote><p>På eliteniveau er forskellen sjældent teknikken – det er beslutningstagningen. Det hold, der laver færrest taktiske fejl, vinder.</p></blockquote><p>Læs spillet. Kend dine styrker. Udnyt deres svagheder. Udfør med selvtillid.</p>',58)),n(c)])}]]);export{g as __pageData,u as default};
